// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "could you add a tab where i will be able to define properties"
// Changes: Formal grammar definition G = (N, T, P, S) – parsing of the declared N and T, consistency checks
//          against the rules P from the LL tab, and helpers that fill N and T from the rules.

import type { LLAnalysis, Problem, Rule } from './grammar'
import type { ProjectData } from './project'

export interface SymbolDecl {
  symbol: string
  note: string
  line: number
}

// One symbol per line, the rest of the line is an optional note; empty lines and '#' lines are skipped.
export function parseDecls(text: string): SymbolDecl[] {
  const out: SymbolDecl[] = []
  ;(text || '').split('\n').forEach((raw, idx) => {
    const line = raw.trim()
    if (!line || line.startsWith('#')) return
    const m = line.match(/^(?:'([^']*)'|"([^"]*)"|(\S+))\s*(.*)$/)
    const symbol = m ? (m[1] ?? m[2] ?? m[3]) : ''
    if (symbol) out.push({ symbol, note: m![4], line: idx + 1 })
  })
  return out
}

const quote = (s: string) => (/\s|^['"#]/.test(s) ? (s.includes("'") ? `"${s}"` : `'${s}'`) : s)

// Appends symbols as new declaration lines.
export function appendDecls(text: string, symbols: string[]) {
  if (!symbols.length) return text
  const base = text.replace(/\s+$/, '')
  return (base ? base + '\n' : '') + symbols.map(quote).join('\n') + '\n'
}

const uniq = (xs: string[]) => [...new Set(xs)]

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "LL by teraz mala pouzivat gramatiku, ktoru si vytvorim v tabulke definicia"
// Changes: Also reports syntax errors of P (the rules are now edited in the Definition tab).
export function analyzeDefinition(def: ProjectData['def'], a: LLAnalysis | null, errors: string[] = []) {
  const rules: Rule[] = a?.rules ?? []
  const nDecl = parseDecls(def.nonterminals)
  const tDecl = parseDecls(def.terminals)
  const declN = uniq(nDecl.map((d) => d.symbol))
  const declT = uniq(tDecl.map((d) => d.symbol))
  const inN = new Set(declN)
  const inT = new Set(declT)
  const declared = declN.length > 0 || declT.length > 0

  const lhs = uniq(rules.map((r) => r.lhs))
  const isLhs = new Set(lhs)
  const used = uniq(rules.flatMap((r) => r.rhs))

  // Effective components: the declarations when given, otherwise what the rules imply.
  const N = declN.length ? declN : lhs
  const T = declT.length ? declT : uniq(used.filter((s) => !isLhs.has(s)))
  const S = def.start || a?.N[0] || ''

  const missingN = lhs.filter((s) => !inN.has(s) && !inT.has(s))
  const missingT = used.filter((s) => !isLhs.has(s) && !inN.has(s) && !inT.has(s))

  const probs: Problem[] = errors.map((text) => ({ level: 'bad', text }))
  const bad = (text: string) => probs.push({ level: 'bad', text })
  const warn = (text: string) => probs.push({ level: 'warn', text })
  const info = (text: string) => probs.push({ level: 'info', text })

  const dupes = (decls: SymbolDecl[], set: string) => {
    const seen = new Map<string, number>()
    decls.forEach((d) => {
      if (seen.has(d.symbol)) warn(`${d.symbol} je v ${set} dvakrát (riadky ${seen.get(d.symbol)} a ${d.line})`)
      else seen.set(d.symbol, d.line)
    })
  }
  dupes(nDecl, 'N')
  dupes(tDecl, 'T')
  declN.filter((s) => inT.has(s)).forEach((s) => bad(`${s} je v N aj v T – musí platiť N ∩ T = ∅`))

  if (!rules.length && !errors.length) info('P je prázdna – zatiaľ žiadne pravidlá.')

  if (!def.start) {
    if (a) info(`S nie je zadaný – použije sa ľavá strana prvého pravidla (${a.N[0]}).`)
  } else {
    if (declN.length && !inN.has(def.start)) bad(`S = ${def.start} nie je v N`)
    if (rules.length && !isLhs.has(def.start)) bad(`S = ${def.start} nemá v P žiadne pravidlo`)
  }

  if (declared) {
    missingN.forEach((s) => bad(`${s} je na ľavej strane pravidla, ale nie je v N`))
    lhs.filter((s) => inT.has(s) && !inN.has(s)).forEach((s) => bad(`${s} je v T, ale je na ľavej strane pravidla (A → x vyžaduje A ∈ N)`))
    missingT.forEach((s) => {
      const r = rules.findIndex((x) => x.rhs.includes(s))
      bad(`Symbol ${s} (pravidlo ${r + 1}) nie je v N ani v T – x ∈ (N ∪ T)*`)
    })
    if (rules.length) {
      // AI generated by: Claude Code / claude-opus-5-5
      // Prompt: "LL by teraz mala pouzivat gramatiku, ktoru si vytvorim v tabulke definicia"
      // Changes: Declared nonterminals stay nonterminals in the LL analysis now.
      declN.filter((s) => !isLhs.has(s)).forEach((s) => warn(`${s} je v N, ale nemá v P žiadne pravidlo (prázdny riadok LL tabuľky)`))
      declT.filter((s) => !used.includes(s)).forEach((s) => info(`Terminál ${s} sa v P nepoužíva`))
    }
  } else if (rules.length) {
    info('N a T nie sú deklarované – odvodzujú sa z pravidiel. „Doplniť z pravidiel“ ich vypíše.')
  }

  if (declared && !probs.some((p) => p.level === 'bad')) {
    probs.unshift({ level: 'ok', text: `G = (N, T, P, S) je konzistentná: |N| = ${N.length}, |T| = ${T.length}, |P| = ${rules.length}, S = ${S || '–'}` })
  }

  const notes = new Map<string, string>()
  ;[...nDecl, ...tDecl].forEach((d) => d.note && !notes.has(d.symbol) && notes.set(d.symbol, d.note))

  return { N, T, S, rules, notes, missingN, missingT, declared, problems: probs }
}

export type DefinitionAnalysis = ReturnType<typeof analyzeDefinition>

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "this is yanked format from our code base could you add a format button into the input field that would make it into corrent format"
// Changes: Formats N/T input into one symbol per line with aligned notes. Accepts a C enum body pasted from the
//          code base (`A, B = 3, // note`, /* comments */, `typedef enum {` / `} name;`) as well as the native format.
export function formatDecls(text: string) {
  const src = text || ''
  const isEnum = /[,{}]|\benum\b/.test(src)
  const items: { symbol: string; note: string }[] = []
  const comments: string[] = []

  if (isEnum) {
    const body = src
      .replace(/\/\*[\s\S]*?\*\//g, ' ')
      .replace(/\btypedef\b|\benum\b/g, ' ')
      .replace(/[A-Za-z_]\w*\s*\{/g, '{')
      .replace(/\}\s*[A-Za-z_]\w*\s*;?/g, '}')
      .replace(/[{};]/g, ',')
    for (const line of body.split('\n')) {
      const [code, ...rest] = line.split('//')
      const note = rest.join('//').trim()
      const parts = code.split(',').map((p) => p.replace(/=.*$/, '').trim())
      const symbols = parts.filter(Boolean).map((p) => p.split(/\s+/)[0])
      // A trailing `// note` belongs to the last enumerator on its line.
      symbols.forEach((symbol, i) => items.push({ symbol, note: i === symbols.length - 1 ? note : '' }))
    }
  } else {
    for (const line of src.split('\n')) {
      const trimmed = line.trim()
      if (trimmed.startsWith('#')) comments.push(trimmed)
      else items.push(...parseDecls(trimmed).map(({ symbol, note }) => ({ symbol, note: note.trim() })))
    }
  }

  const seen = new Map<string, { symbol: string; note: string }>()
  for (const it of items) {
    const prev = seen.get(it.symbol)
    if (!prev) seen.set(it.symbol, { ...it })
    else if (!prev.note && it.note) prev.note = it.note
  }
  const list = [...seen.values()].map((it) => ({ ...it, symbol: quote(it.symbol) }))
  const width = Math.max(0, ...list.filter((it) => it.note).map((it) => it.symbol.length))
  const lines = list.map((it) => (it.note ? `${it.symbol.padEnd(width)}  ${it.note}` : it.symbol))
  return [...comments, ...lines].join('\n') + (lines.length || comments.length ? '\n' : '')
}
